import{document}from"../../build/spruceStdlib.min.js";import{sitemap}from"./sitemap.min.js";function bannerDocument(body){return`<div id="banner">
	<div id="banner-small"></div>
	<div id="banner-large"></div>
</div>

<div id="content-container">
	<div id="content">
		${document(body)}
	</div>
</div>`}const gap='<div style="height: 32px"></div>';function carousel(...blocks){return`
		<div class="carousel">
			<div class="carousel-content">
				${blocks.map(block=>`<div class="carousel-entry">${block}</div>`).join("")}
			</div>

			<div class="carousel-dots">
				${'<div class="carousel-dot"><div class="fill"></div></div>'.repeat(blocks.length)}
			</div>
		</div>
	`}function clickTap(clickText,tapText){return`<span class="click-tap"><span>${clickText}</span><span>${tapText}</span></span>`}function galleryBlock(...data){if(data.length%2!=0)throw new Error("Invalid number of arguments");let t='<div class="gallery-block">';for(let i=0;i<data.length;i+=2){var e=data[i],n=data[i+1];t+=`
		<div class="gallery-image-${n}-${n}">
			<img src="/graphics/general-icons/placeholder.png" data-src="/gallery/thumbnails/${e}.webp" data-image-id="${e}" />
		</div>`}return t+"</div>"}function imageLinks(data){return`<div style="display: flex; justify-content: center; width: 100%;">
	<div class="image-links">${data.map(item=>{var t=resolveUrl((item="string"==typeof item?{url:item}:item).url),e=t.split(".")[0].split("/"),e=e[e.length-1];if(void 0===item.name&&void 0===sitemap[t]&&void 0===item.coverPath)throw new Error(t+" is not in sitemap!");var n,i=item.name??sitemap[t].title;return item.forCard?`
				<a href="${n=t.slice(0,t.lastIndexOf("/"))}/?card=${e}" data-card-id="${e}" class="image-link">
					<img src="/graphics/general-icons/placeholder.png" data-src="${item.coverPath??n+`/cards/${e}/cover.webp`}" alt="${i}" tabindex="1" />
					
					<p class="image-link-subtext">${i}</p>
				</a>
			`:(n=t.includes(".")?t.slice(0,t.lastIndexOf("/"))+"/cover.webp":t+"/cover.webp",`
		<a href="${t}"${item.inNewTab?' data-in-new-tab="1"':""} class="image-link">
			<img src="/graphics/general-icons/placeholder.png" data-src="${item.coverPath??n}" alt="${i}" tabindex="1" />
			
			<p class="image-link-subtext">${i}</p>
		</a>`)}).join("")}</div>
</div>`}function card(id,name,body){return name?`<div id="${id}-card" class="card"><h1 class="heading-text">${name}</h1>${body}</div>`:`<div id="${id}-card" class="card">${body}</div>`}function externalCard(id){return`<div id="${id}-card" class="card external-card"></div>`}function debug(body){return`<div class="DEBUG">${body}</div>`}function center(body){return`<p class="body-text center-if-needed"><span>${body}</span></p>`}function resolveUrl(url){var t;return url.startsWith("http")||(t=(t=globalThis.filePath.replace(/^.+?cruzgodar\.github\.io/,"")).slice(0,t.lastIndexOf("/")),"/"===url[0])?url:t+"/"+url}const controlsFunctions={slider:slider,textarea:textarea,button:button,navButtons:navButtons,dropdown:dropdown,fileUpload:fileUpload,checkbox:checkbox,textBox:textBox};function controls(data){let t='<div class="applet-controls">';for(var[e,n]of Object.entries(data)){if(!controlsFunctions[n])throw new Error(n+" is not a valid control type");t=""+t+controlsFunctions[n](e)}return t+"</div>"}function slider(id){return`
		<div class="slider-container">
			<div class="slider-bar"></div>
			<div id="${id}Slider" class="slider-thumb"></div>
			<p class="body-text slider-subtext"></p>
		</div>
	`}function textarea(id){return`
		<div class="text-field-container">
			<div class="textarea-wrapper">
				<textarea cols="16" rows="4" name="${id}Textarea" id="${id}-textarea" class="text-field" spellcheck="false" autocapitalize="off" autocomplete="off" autocorrect="off"></textarea>
				<div class="textarea-overlay"></div>
			</div>
			<p class="body-text" style="text-align: center"></p>
		</div>
	`}function button(id){return`
		<div class="focus-on-child" tabindex="1">
			<button class="text-button" type="button" id="${id}Button" tabindex="-1"></button>
		</div>
	`}function navButtons(){return`
		<div class="applet-controls nav-buttons">
			<div class="focus-on-child" tabindex="1">
				<button class="text-button linked-text-button nav-button previous-nav-button" type="button" tabindex="-1">Previous</button>
			</div>
			
			<div class="focus-on-child" tabindex="1">
				<button class="text-button linked-text-button nav-button home-nav-button" type="button" tabindex="-1">Home</button>
			</div>
			
			<div class="focus-on-child" tabindex="1">
				<button class="text-button linked-text-button nav-button next-nav-button" type="button" tabindex="-1">Next</button>
			</div>
		</div>
	`}function dropdown(id){return`
		<div class="dropdown-holder">
			<div class="dropdown-container focus-on-child" tabindex="1">
				<button class="text-button dropdown" type="button" id="${id}-dropdown-button" tabindex="-1"></button>
				<select id="${id}Dropdown"></select>
			</div>
		</div>
	`}function fileUpload(id,accept,multiple=""){return`
		<div class="text-buttons">
			<div class="focus-on-child dropdown-container" tabindex="1">
				<button class="text-button file-upload" type="button" id="${id}-upload-button" tabindex="-1"></button>
				<input type="file" id="${id}Upload" style="display: none" accept="${accept}" ${multiple}>
			</div>
		</div>
	`}function checkbox(id){return`
		<div class="checkbox-row">
			<div class="checkbox-container" tabindex="1">
				<input type="checkbox" id="${id}Checkbox">
				<div class="checkbox"></div>
			</div>
			
			<label for="${id}-checkbox" style="margin-left: 10px">
				<p class="body-text checkbox-subtext"></p>
			</label>
		</div>
	`}function textBox(id){return`
		<div class="text-box-container">
			<input id="${id}Input" class="text-box" type="text" value="" tabindex="1">
			<p class="body-text text-box-subtext"></p>
		</div>
	`}let count=1;function problem(body){var t=`<p class="body-text homework-problem">${count}. ${body}</p>`;return count++,t}function problemNumber(offset){return count+offset}function problemNumberRange(startOffset,stopOffset){return count+startOffset+"&ndash;"+(count+stopOffset)}function problemNumberNextRange(length){return problemNumberRange(0,length-1)}function problemNumberPreviousRange(length){return problemNumberRange(-length,-1)}export{bannerDocument,gap,carousel,clickTap,galleryBlock,imageLinks,card,externalCard,debug,center,controls,problem,problemNumber,problemNumberRange,problemNumberNextRange,problemNumberPreviousRange};